#!/usr/bin/env python3
"""Validate and append the .ai/data records.

The checker reads .ai/schema/*.json and applies required, type, enum,
minLength, minItems, items, and additionalProperties. A record the schema
rejects is a failed check, including records already on disk.

  python .ai/machine/organize.py --check
  python .ai/machine/organize.py --self-test
  python .ai/machine/organize.py journal --session KEY --type decision_made --content "..."
"""

from __future__ import annotations

import argparse
import datetime as dt
import json
import sys
import uuid
from pathlib import Path
from typing import Any


ROOT = Path(__file__).resolve().parents[2]
SCHEMA = ROOT / ".ai" / "schema"
DATA = ROOT / ".ai" / "data"

LINE_SCHEMAS = {
    "events.jsonl": "session-event.schema.json",
    "messages.jsonl": "agent-message.schema.json",
    "tools.jsonl": "tool-event.schema.json",
    "reasoning.jsonl": "reasoning.schema.json",
}


def now() -> str:
    return dt.datetime.now(dt.UTC).isoformat()


def load_schema(name: str) -> dict[str, Any]:
    return json.loads((SCHEMA / name).read_text(encoding="utf-8"))


def fail(path: str, detail: str) -> None:
    raise ValueError(f"{path}: {detail}")


def check_node(schema: dict[str, Any], value: Any, path: str) -> None:
    expected = schema.get("type")
    if isinstance(expected, list):
        if not any(_is_type(value, item) for item in expected):
            fail(path, f"type {type(value).__name__} not in {expected}")
        if value is None:
            return
    elif expected and not _is_type(value, expected):
        fail(path, f"type {type(value).__name__} is not {expected}")
        return
    if isinstance(value, str):
        min_length = schema.get("minLength")
        if isinstance(min_length, int) and len(value) < min_length:
            fail(path, f"shorter than {min_length}")
    enum = schema.get("enum")
    if enum is not None and value not in enum:
        fail(path, f"{value!r} not in {enum}")
    if not isinstance(value, dict):
        if isinstance(value, list) and "items" in schema:
            min_items = schema.get("minItems")
            if isinstance(min_items, int) and len(value) < min_items:
                fail(path, f"fewer than {min_items} items")
            for index, item in enumerate(value):
                check_node(schema["items"], item, f"{path}[{index}]")
        return
    if schema.get("additionalProperties") is False:
        allowed = set(schema.get("properties") or {})
        extra = set(value) - allowed
        if extra:
            fail(path, f"unknown fields {sorted(extra)}")
    for name in schema.get("required") or []:
        if name not in value:
            fail(path, f"missing {name}")
    for name, prop in (schema.get("properties") or {}).items():
        if name in value:
            check_node(prop, value[name], f"{path}.{name}")


def _is_type(value: Any, expected: str) -> bool:
    if expected == "object":
        return isinstance(value, dict)
    if expected == "array":
        return isinstance(value, list)
    if expected == "string":
        return isinstance(value, str)
    if expected == "integer":
        return isinstance(value, int) and not isinstance(value, bool)
    if expected == "boolean":
        return isinstance(value, bool)
    if expected == "null":
        return value is None
    return False


def check_jsonl(path: Path, schema_name: str, errors: list[str]) -> int:
    if not path.is_file():
        return 0
    schema = load_schema(schema_name)
    count = 0
    for number, line in enumerate(path.read_text(encoding="utf-8").splitlines(), start=1):
        if not line.strip():
            continue
        count += 1
        where = f"{path}:{number}"
        try:
            row = json.loads(line)
            check_node(schema, row, where)
        except (json.JSONDecodeError, ValueError) as exc:
            errors.append(str(exc) if isinstance(exc, ValueError) else f"{where}: invalid json")
    return count


def check_tree(data: Path = DATA) -> dict[str, int]:
    errors: list[str] = []
    counts = {"events": 0, "messages": 0, "tools": 0, "reasoning": 0, "journal": 0, "plans": 0}
    sessions = data / "sessions"
    if sessions.is_dir():
        for session in sorted(p for p in sessions.iterdir() if p.is_dir()):
            for filename, schema_name in LINE_SCHEMAS.items():
                counts[filename.split(".")[0] if filename != "reasoning.jsonl" else "reasoning"] += check_jsonl(
                    session / filename, schema_name, errors
                )
    counts["journal"] = check_jsonl(data / "journal" / "journal.jsonl", "journal-entry.schema.json", errors)
    roadmap = data / "roadmap" / "roadmap.json"
    if roadmap.is_file():
        try:
            check_node(load_schema("roadmap.schema.json"), json.loads(roadmap.read_text(encoding="utf-8")), str(roadmap))
        except (json.JSONDecodeError, ValueError) as exc:
            errors.append(str(exc))
    else:
        errors.append(f"missing {roadmap}")
    plans = data / "plans"
    if plans.is_dir():
        for path in sorted(plans.glob("*.json")):
            counts["plans"] += 1
            try:
                row = json.loads(path.read_text(encoding="utf-8"))
                check_node(load_schema("plan.schema.json"), row, str(path))
                if row.get("status") == "implemented":
                    for index, step in enumerate(row.get("verification") or []):
                        if not str(step.get("result") or "").strip():
                            errors.append(f"{path}: verification[{index}] has no result")
            except (json.JSONDecodeError, ValueError) as exc:
                errors.append(str(exc))
    index = data / "index.json"
    if index.is_file():
        try:
            payload = json.loads(index.read_text(encoding="utf-8"))
            sources = payload.get("sources")
            if not isinstance(sources, dict) or not sources:
                errors.append("index.json has no sources")
            else:
                for source, meta in sources.items():
                    if not Path(source).is_file():
                        errors.append(f"index source missing: {source}")
                    if not isinstance(meta, dict) or "offset" not in meta or "session_key" not in meta:
                        errors.append(f"index source incomplete: {source}")
        except json.JSONDecodeError:
            errors.append("index.json is not json")
    else:
        errors.append("missing index.json")
    if errors:
        raise SystemExit("\n".join(errors))
    return counts


def append_journal(session_key: str, entry_type: str, content: str, agent_id: str = "main") -> dict[str, Any]:
    entry = {
        "entry_id": uuid.uuid4().hex,
        "project_key": "shippin-tech",
        "session_key": session_key,
        "agent_id": agent_id,
        "entry_type": entry_type,
        "content": content,
        "related_args": {},
        "related_result": {},
        "source": "organize",
        "created_at": now(),
    }
    check_node(load_schema("journal-entry.schema.json"), entry, "journal")
    path = DATA / "journal" / "journal.jsonl"
    path.parent.mkdir(parents=True, exist_ok=True)
    with path.open("a", encoding="utf-8") as handle:
        handle.write(json.dumps(entry, separators=(",", ":"), ensure_ascii=False) + "\n")
    return entry


def self_test() -> None:
    schema = load_schema("journal-entry.schema.json")
    bad = {
        "entry_id": "0123456789abcdef",
        "project_key": "shippin-tech",
        "session_key": "self-test",
        "agent_id": "main",
        "entry_type": "not-a-real-type",
        "content": "nope",
        "source": "organize",
        "created_at": now(),
    }
    try:
        check_node(schema, bad, "bad")
    except ValueError:
        pass
    else:
        raise SystemExit("invalid journal entry was accepted")
    good = dict(bad)
    good["entry_type"] = "decision_made"
    check_node(schema, good, "good")
    counts = check_tree()
    if counts["events"] < 1 or counts["messages"] < 1 or counts["tools"] < 1:
        raise SystemExit(f"filed chats did not validate: {counts}")
    print(json.dumps({"ok": True, **counts}))


def main() -> None:
    parser = argparse.ArgumentParser()
    mode = parser.add_mutually_exclusive_group(required=True)
    mode.add_argument("--check", action="store_true")
    mode.add_argument("--self-test", action="store_true")
    mode.add_argument("--journal", action="store_true")
    parser.add_argument("--session", default="shippin-tech")
    parser.add_argument("--type", default="decision_made")
    parser.add_argument("--content", default="")
    args = parser.parse_args()
    if args.self_test:
        self_test()
        return
    if args.check:
        print(json.dumps(check_tree()))
        return
    if not args.content.strip():
        raise SystemExit("journal content is empty")
    print(json.dumps(append_journal(args.session, args.type, args.content)))


if __name__ == "__main__":
    try:
        main()
    except BrokenPipeError:
        sys.exit(0)

